def _asc(font, fs):
    return pdfmetrics.getAscent(font) / 1000.0 * fs

def _ty(y):
    return H - y

def _txt(c, x, ytop, font, fs, color, s, cs=0.0, center=None, right=None):
    w = pdfmetrics.stringWidth(s, font, fs) + cs * max(len(s) - 1, 0)
    if center is not None: x = center - w / 2.0
    if right is not None:  x = right - w
    t = c.beginText(); t.setFont(font, fs); t.setCharSpace(cs)
    t.setFillColor(color); t.setTextOrigin(x, _ty(ytop + _asc(font, fs)))
    t.textOut(s); c.drawText(t)
    return x + w

def _wrap(s, font, fs, width):
    out, cur = [], ''
    for w in str(s).split():
        trial = (cur + ' ' + w).strip()
        if pdfmetrics.stringWidth(trial, font, fs) <= width or not cur:
            cur = trial
        else:
            out.append(cur); cur = w
    if cur: out.append(cur)
    return out

def _rr(c, x, ytop, w, h, r, fill=None, stroke=None, sw=1.5):
    if fill is not None: c.setFillColor(fill)
    if stroke is not None:
        c.setStrokeColor(stroke); c.setLineWidth(sw)
    c.roundRect(x, _ty(ytop + h), w, h, r, stroke=1 if stroke is not None else 0,
                fill=1 if fill is not None else 0)

def _page_frame(c):
    c.setFillColor(CREAM); c.rect(0, 0, W, H, stroke=0, fill=1)
    c.saveState(); c.setStrokeColor(NAVY); c.setLineWidth(1.73); c.setStrokeAlpha(0.08)
    for r in (31.1, 57.0, 82.95):
        c.circle(550.6, _ty(666.1), r, stroke=1, fill=0)
    c.restoreState()
    c.setFillColor(NAVY); c.rect(0, 0, W, 29.2, stroke=0, fill=1)
    x = _txt(c, 33.1, 770.0, 'Anton', 9.8, HexColor('#FFFFFF'), 'HOOPSPHERE')
    x = _txt(c, x + 4.1, 770.0, 'Anton', 9.8, ORANGE, '//')
    _txt(c, x + 2.4, 770.0, 'Anton', 9.8, HexColor('#FFFFFF'), 'BASKETBALL ACADEMY')
    _txt(c, 509.7, 770.2, 'BSemi', 9.0, HexColor('#FFFFFF'), 'hoopsphere.com')

def _header(c, title, pill=None):
    c.drawImage(LOGO, 33.0, _ty(28.5 + 46.5), 46.5, 46.5, mask='auto')
    _txt(c, 88.6, 30.9, 'Anton', 20.2, NAVY, 'HOOPSPHERE')
    _txt(c, 88.6, 59.6, 'BSemi', 7.1, NAVY, 'BASKETBALL ACADEMY', cs=2.6)
    if pill:
        pw = pdfmetrics.stringWidth(pill, 'BBold', 6.8) + 1.5 * (len(pill) - 1) + 22
        _rr(c, RX - pw, 43.1, pw, 18, 9, stroke=ORANGE, sw=0.75)
        _txt(c, 0, 48.0, 'BBold', 6.8, ORANGE, pill, cs=1.5, center=RX - pw / 2)
    _txt(c, 33.1, 85.5, 'Anton', 28.5, NAVY, title)

def _section(c, ytop, label):
    c.setFillColor(ORANGE)
    c.circle(33.0 + 3.4, _ty(ytop + 7.0 + 3.4), 3.4, stroke=0, fill=1)
    _txt(c, 45.9, ytop, 'Anton', 14.2, NAVY, label)

def _medal(c, x, ytop, s=1.0):
    c.setFillColor(ORANGE); c.rect(x + 1.1*s, _ty(ytop + 4.9*s), 2.6*s, 4.9*s, stroke=0, fill=1)
    c.setFillColor(NAVY);   c.rect(x + 3.0*s, _ty(ytop + 4.9*s), 2.6*s, 4.9*s, stroke=0, fill=1)
    c.setFillColor(MEDAL); c.setStrokeColor(MEDALS); c.setLineWidth(0.65*s)
    c.circle(x + 3.9*s, _ty(ytop + 8.4*s), 4.0*s, stroke=1, fill=1)
    c.setFillColor(CHIP_F)
    c.circle(x + 3.9*s, _ty(ytop + 8.4*s), 2.3*s, stroke=0, fill=1)

def _mi_chip(c, x, ytop, skill, label_fs, name_fs, h):
    lead = 22.8 if skill else 18.0
    lw = pdfmetrics.stringWidth('MOST IMPROVED', 'BBold', label_fs) + 1.5 * 12
    nw = (pdfmetrics.stringWidth(skill, 'BBold', name_fs) + 6) if skill else 0
    w = lead + lw + nw + 12
    _rr(c, x, ytop, w, h, h / 2, fill=CHIP_F, stroke=CHIP_S, sw=0.75)
    _medal(c, x + 7.2, ytop + 3.2, s=h / 20.2)
    ty0 = ytop + (h - label_fs) / 2 - 1.2
    _txt(c, x + lead, ty0, 'BBold', label_fs, CHIP_T, 'MOST IMPROVED', cs=1.5)
    if skill:
        _txt(c, x + lead + lw + 6, ytop + (h - name_fs) / 2 - 1.2, 'BBold', name_fs, NAVY, skill)
    return w

def _pill(c, x, ytop, text, fill, tcolor, h=15.0, fs=7.5, cs=0.8, right=None):
    w = pdfmetrics.stringWidth(text, 'BBold', fs) + cs * (len(text) - 1) + 16.4
    if right is not None: x = right - w
    _rr(c, x, ytop, w, h, h / 2, fill=fill)
    _txt(c, 0, ytop + (h - fs) / 2 - 1.0, 'BBold', fs, tcolor, text, cs=cs, center=x + w / 2)
    return x, w

# ------------------------------------------------------------------ page 1
def _page1(c, d):
    _page_frame(c)
    _header(c, 'PLAYER PROGRESS REPORT')
    # info bar
    _rr(c, MX, 125.2, CW, 39.0, 8, stroke=NAVY)
    cols = [43.6, 204.2, 315.4, 450.7]
    for dx in (194.2, 305.2, 441.0):
        c.setFillColor(NAVY); c.rect(dx, _ty(126.0 + 37.5), 0.8, 37.5, stroke=0, fill=1)
    labels = ['PLAYER', 'DATE', 'COACH', 'PROGRAM ADVISOR']
    vals = [d['player'], d['date'], d['coach'], d['advisor']]
    for x, lab, val in zip(cols, labels, vals):
        _txt(c, x, 133.1, 'BBold', 6.4, ORANGE, lab, cs=1.6)
        _txt(c, x, 143.2, 'BSemi', 10.5, NAVY, str(val))
    # evaluation scale
    _rr(c, MX, 173.2, CW, 74.2, 8, stroke=NAVY)
    _txt(c, 45.1, 179.6, 'Anton', 10.5, NAVY, 'EVALUATION SCALE')
    x = 136.5
    for lab, desc in [('EXCELLING', 'ahead of the bar'), ('ON TRACK', 'right where we expect'),
                      ('BUILDING', 'still coming together')]:
        fill, tc = RATING[{'EXCELLING': 'Excelling', 'ON TRACK': 'On Track', 'BUILDING': 'Building'}[lab]]
        px, pw = _pill(c, x, 180.8, lab, fill, tc)
        dx = _txt(c, px + pw + 6.1, 183.0, 'B', 8.2, NAVY, desc)
        x = dx + 14.0
    for i, b in enumerate(['Every player is graded against their age group.',
                           'Scores reflect this quarter only.',
                           "Basketball progression is not linear. Expectations rise with age, so proficiency can go up or down while a player is still improving. That's normal."]):
        yt = [202.5, 216.0, 228.8][i]
        c.setFillColor(NAVY); c.rect(46.5, _ty([207.0, 220.5, 233.2][i] + 3.0), 3.0, 3.0, stroke=0, fill=1)
        _txt(c, 57.1, yt, 'B', 8.2, NAVY, b)
    # breakdown
    _section(c, 257.0, 'THE BREAKDOWN')
    _mi_chip(c, RX - _chip_w(d['most_improved'], 6.8, 9.4), 257.6, d['most_improved'], 6.8, 9.4, 20.2)
    rows, y = [], 285.8
    for sk in SKILLS_V2:
        e = d['skills'][sk]
        lines = _wrap(e['comment'], 'B', 9.0, RX - 91.5 - 14)
        mi = (sk == d['most_improved'])
        bump = 4.4 if mi else 0.0
        rh = 40.4 + bump + max(len(lines), 1) * 12.8 + 8.3
        rows.append((sk, e, lines, mi, bump, y, rh))
        y += rh
    box_h = (y - 285.8) + 1.5
    if 285.0 + box_h > 560.0:
        raise RuntimeError('Page 1 overflow: skill comments are too long. Shorten the longest comment.')
    _rr(c, MX, 285.0, CW, box_h, 10, stroke=NAVY)
    c.saveState()
    p = c.beginPath(); p.roundRect(MX + 0.75, _ty(285.0 + box_h - 0.75), CW - 1.5, box_h - 1.5, 9.5)
    c.clipPath(p, stroke=0, fill=0)
    for sk, e, lines, mi, bump, ry, rh in rows:
        fill, _tc = RATING[e['rating']]
        c.setFillColor(fill); c.rect(34.5, _ty(ry + rh), 6.0, rh, stroke=0, fill=1)
    c.restoreState()
    for i, (sk, e, lines, mi, bump, ry, rh) in enumerate(rows):
        if i:
            c.setFillColor(NAVY); c.rect(34.5, _ty(ry + 0.4), 543.0, 0.8, stroke=0, fill=1)
        tx = _txt(c, 51.1, ry + 8.6 + bump, 'BSemi', 11.6, NAVY, sk)
        if mi:
            _mi_chip(c, tx + 4.0, ry + 9.4, None, 6.4, 0, 15.8)
        _txt(c, 51.1, ry + 22.8 + bump, 'B', 7.9, NAVY, SKILL_SUB[sk])
        fill, tc = RATING[e['rating']]
        _pill(c, 0, ry + 12.7, e['rating'].upper(), fill, tc, right=565.5)
        _txt(c, 51.1, ry + 40.4 + bump, 'BBold', 6.4, NAVY, 'COMMENTS', cs=0.7)
        for j, ln in enumerate(lines):
            _txt(c, 91.5, ry + 40.4 + bump + j * 12.8, 'B', 9.0, NAVY, ln)
    bd_bottom = 285.0 + box_h
    # note from coach
    nt = bd_bottom + 14.0
    _section(c, nt, 'NOTE FROM COACH')
    nb = nt + 28.0
    nlines = _wrap(d['coach_note'], 'B', 9.8, CW - 2 * 15.8)
    nh = 14.3 + len(nlines) * 15.0 + 6.8 + 11.0 + 10.7
    if nb + nh > 737.0:
        raise RuntimeError('Page 1 overflow: the coach note is too long. Trim it by a sentence.')
    _rr(c, MX, nb, CW, nh, 10, fill=HexColor('#FFFFFF'), stroke=NAVY)
    for j, ln in enumerate(nlines):
        _txt(c, 49.6, nb + 14.3 + j * 15.0, 'B', 9.8, NAVY, ln)
    sig_y = nb + nh - 21.8
    nmw = pdfmetrics.stringWidth(str(d['coach']), 'BItal', 8.2)
    _txt(c, 564.2 - nmw - 7.2, sig_y, 'BSemi', 8.2, NAVY, '—')
    _txt(c, 564.2 - nmw, sig_y, 'BItal', 8.2, NAVY, str(d['coach']))
    first = str(d['player']).split()[0]
    _txt(c, 0, 746.6, 'B', 7.9, NAVY,
         f"Questions about {first}'s development? Call {FOOT_PHONE} or ask for the Program Advisor · {FOOT_MAIL}",
         center=W / 2)

def _chip_w(skill, label_fs, name_fs):
    return 22.8 + pdfmetrics.stringWidth('MOST IMPROVED', 'BBold', label_fs) + 1.5 * 12 + 6 + \
           pdfmetrics.stringWidth(skill, 'BBold', name_fs) + 12

